1	<!doctype html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="utf-8"><title>CMDB 空间拓扑、灰度验证 & SLA 审计台</title>
5	<style>
6	body{font-family:system-ui,sans-serif;background:#f1f5f9;margin:0;color:#0f172a}
7	header{background:#0f172a;color:#fff;padding:14px 24px;display:flex;justify-content:space-between;align-items:center}
8	.tabs{display:flex;gap:8px;padding:12px 24px;background:#fff;border-bottom:1px solid #cbd5e1}
