10	.tab.active{background:#2563eb;color:#fff;border-color:#2563eb}
11	.container{padding:24px;max-width:1280px;margin:0 auto}
12	.panel{display:none;background:#fff;padding:20px;border-radius:10px;box-shadow:0 1px 4px rgba(0,0,0,.08)}
13	.panel.active{display:block}
14	.topo-wrap{display:grid;grid-template-columns:2fr 1fr;gap:20px;align-items:start}
15	.inspector{background:#f8fafc;border:1px solid #cbd5e1;border-radius:8px;padding:16px}
16	.topo-legend{display:flex;flex-wrap:wrap;gap:14px;color:#475569;font-size:13px;margin:10px 0}
17	.node-g:focus-visible rect,.node-g[aria-pressed="true"] rect{stroke:#1d4ed8;stroke-width:4}
18	.node-error{color:#991b1b}
19	@media (max-width:900px){.topo-wrap{grid-template-columns:1fr}}
20	table{width:100%;border-collapse:collapse;margin-top:12px;font-size:13px}
21	th,td{border:1px solid #e2e8f0;padding:8px;text-align:left}
22	th{background:#f8fafc}
23	.badge{padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600;display:inline-block}
24	.ACTIVE,.CANARY_PASSED,.APPROVED{background:#dcfce7;color:#166534}
25	.DEGRADED,.CANARY_FAILED{background:#fee2e2;color:#991b1b}
26	.ISOLATED,.DRAINED,.PENDING{background:#fef3c7;color:#92400e}
27	.LOCKED{background:#e2e8f0;color:#475569}
28	.AUDITED,.DRAFT{background:#dbeafe;color:#1e40af}
29	input,select{padding:6px 8px;border:1px solid #cbd5e1;border-radius:5px}
30	button{padding:6px 12px;border:none;border-radius:5px;background:#2563eb;color:#fff;cursor:pointer;font-size:13px}
31	button.warn{background:#d97706} button.ok{background:#16a34a}
32	button:disabled{background:#94a3b8;cursor:not-allowed}
33	.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:12px}
34	svg text{user-select:none}
35	.node-g{cursor:pointer}
36	</style>
37	</head>
38	<body>
39	<header><strong>跨境清结算平台 — CMDB 空间拓扑 / 灰度门禁 / SLA 审计控制台</strong><span>sre_oncall</span></header>
40	<div class="tabs">
41	  <button class="tab active" onclick="showTab('cmdb',this)">1. CMDB 空间拓扑图</button>
42	  <button class="tab" onclick="showTab('changes',this)">2. 变更发布与灰度回放门禁</button>
43	  <button class="tab" onclick="showTab('sla',this)">3. SLA 赔付审计台</button>
44	</div>
45	<div class="container">
46	  <div id="cmdb" class="panel active">
47	    <h3>故障时段调用拓扑</h3>
48	    <p>箭头从调用方指向被调用方。用 Grafana 节点曲线确认告警出现的先后，再选择要隔离的节点。</p>
49	    <div class="topo-wrap">
50	      <div>
51	        <svg id="topo-svg" viewBox="0 0 866 430" aria-labelledby="topo-title topo-desc" style="width:100%;border:1px solid #cbd5e1;border-radius:8px;background:#f8fafc">
52	          <title id="topo-title">清结算请求调用拓扑</title>
53	          <desc id="topo-desc">实线是事故期间的请求方向，虚线是预留路径。告警表示观测延迟升高。</desc>
54	          <defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 1 L 10 5 L 0 9 z" fill="#475569"/></marker></defs>
55	          <rect x="16" y="16" width="224" height="398" rx="10" fill="#eef2ff" stroke="#c7d2fe"/>
56	          <text x="34" y="45" font-size="16" font-weight="700" fill="#3730a3">结算调度</text>
57	          <rect x="314" y="16" width="236" height="398" rx="10" fill="#fff7ed" stroke="#fed7aa"/>
58	          <text x="331" y="45" font-size="16" font-weight="700" fill="#9a3412">风控计算</text>
59	          <rect x="624" y="16" width="226" height="398" rx="10" fill="#f0fdf4" stroke="#bbf7d0"/>
60	          <text x="641" y="45" font-size="16" font-weight="700" fill="#166534">核心数据</text>
61	          <g fill="none" stroke="#475569" stroke-width="2.5" marker-end="url(#arr)">
62	            <path d="M 212 172 H 266 V 126 H 339"/>
63	            <path d="M 212 183 H 280 V 243 H 339"/>
64	            <path d="M 518 126 H 585 V 202 H 648"/>
65	            <path d="M 518 243 H 585 V 217 H 648"/>
66	            <path d="M 212 195 H 257 V 355 H 339" stroke-dasharray="7 4"/>
67	          </g>
68	          <g id="svg-nodes"></g>
69	        </svg>
70	        <div class="topo-legend"><span>实线箭头 · 事故流量</span><span>虚线箭头 · 预留路径</span><span>告警 · 观测延迟升高</span></div>
71	      </div>
72	      <div class="inspector" id="node-inspector">
73	        <h4>节点操作面板</h4>
74	        <p style="color:#64748b;font-size:13px">选择节点查看运行状态和故障时段的观测值。</p>
75	      </div>
76	    </div>
77	    <p id="node-feedback" role="status"></p>
78	    <h4>节点状态核对</h4>
79	    <table id="node-audit"><thead><tr><th>节点</th><th>运行状态</th><th>状态变更次数</th></tr></thead><tbody></tbody></table>
80	  </div>
81	  <div id="changes" class="panel">
82	    <h3>变更发布单与 Gitea 灰度压测回放门禁</h3>
83	    <p style="font-size:13px;color:#475569">提交变更单后须点击「触发灰度回放」拉取 Gitea 代码执行并发/503 压测并同步刷新 Grafana 与 Perfetto (<code>/traces/canary_replay_latest.pftrace</code>)，通过后方可「签发排期」。</p>
84	    <table id="changes-table"><thead><tr><th>单号</th><th>服务</th><th>Commit</th><th>Span</th><th>窗口 (UTC+8)</th><th>灰度门禁</th><th>回放遥测</th><th>状态</th><th>操作</th></tr></thead><tbody></tbody></table>
85	    <h4 style="margin-top:18px">新建变更单 (DRAFT)</h4>
86	    <div class="form-grid">
87	      <input id="chg-svc" placeholder="service (e.g. risk-engine)">
88	      <input id="chg-sha" placeholder="Gitea main commit SHA">
89	      <input id="chg-span" placeholder="bottleneck_span">
90	      <input id="chg-win" placeholder="YYYY-MM-DD HH:MM-HH:MM">
91	      <input id="chg-desc" placeholder="变更说明" style="grid-column:span 2">
92	    </div>
93	    <button style="margin-top:12px" onclick="createChange()">创建变更单</button>
94	  </div>
95	  <div id="sla" class="panel">
96	    <h3>SLA 赔付批次审计台</h3>
97	    <table id="batches-table"><thead><tr><th>批次号</th><th>日期</th><th>商户</th><th>等级</th><th>币种</th><th>结算CNY</th><th>违约笔数</th><th>重复风险</th><th>赔付CNY</th><th>状态</th><th>操作</th></tr></thead><tbody></tbody></table>
98	  </div>
99	</div>
100	<script>
101	const CSRF = "b4de126c0eb96e167ce9672f5072d794";
102	const POS = {
103	  "settle-node-01": [36, 145],
104	  "settle-node-02": [36, 304],
105	  "risk-node-02": [342, 90],
106	  "risk-node-03": [342, 207],
107	  "risk-node-01": [342, 319],
108	  "pg-primary-01": [651, 173]
109	};
110	let nodesCache = [], selectedNode = null;
111	function showTab(id, btn){
112	  document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));
113	  document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));
114	  document.getElementById(id).classList.add('active');
115	  btn.classList.add('active');
116	}
117	function nodeAppearance(r){
118	  if(r.status==='ISOLATED'||r.status==='DRAINED') return ['#fef3c7','#92400e',r.status];
119	  if(r.status==='DEGRADED'||r.p99_ms>=1200) return ['#fee2e2','#991b1b','告警'];
120	  return ['#dcfce7','#166534','正常'];
121	}
122	function renderSvg(){
123	  const g = document.getElementById('svg-nodes');
124	  g.innerHTML = nodesCache.filter(r => Object.hasOwn(POS, r.node_name)).map(r=>{
125	    const [x,y] = POS[r.node_name];
126	    const [bg,bd,label] = nodeAppearance(r);
127	    return `<g class="node-g" role="button" tabindex="0" data-node="${r.node_name}"
128	      aria-label="${r.node_name}，${label}，P99 ${r.p99_ms} 毫秒" aria-pressed="${r.node_name===selectedNode}">
129	      <rect x="${x}" y="${y}" width="176" height="72" rx="8" fill="${bg}" stroke="${bd}" stroke-width="2.5"/>
130	      <text x="${x+10}" y="${y+22}" font-size="13" font-weight="700" fill="#0f172a">${r.node_name}</text>
131	      <text x="${x+10}" y="${y+41}" font-size="11" fill="#334155">${r.service} [${r.role}]</text>
132	      <text x="${x+10}" y="${y+59}" font-size="11" font-weight="600" fill="${bd}">${label} · P99 ${r.p99_ms} ms</text>
133	    </g>`;
134	  }).join('');
135	}
136	const topoNodes = document.getElementById('svg-nodes');
137	topoNodes.addEventListener('click', event => {
138	  const node = event.target.closest('[data-node]');
139	  if (node) selectNode(node.dataset.node);
140	});
141	topoNodes.addEventListener('keydown', event => {
142	  if (event.key !== 'Enter' && event.key !== ' ') return;
143	  const node = event.target.closest('[data-node]');
144	  if (node) {
145	    event.preventDefault();
146	    selectNode(node.dataset.node);
147	  }
148	});
149	function selectNode(name){
150	  selectedNode = name;
151	  const r = nodesCache.find(x=>x.node_name===name);
152	  if(!r) return;
153	  for (const node of topoNodes.querySelectorAll('[data-node]')) {
154	    node.setAttribute('aria-pressed', String(node.dataset.node===name));
155	  }
156	  document.getElementById('node-inspector').innerHTML = `
157	    <h4>${r.node_name}</h4>
158	    <div style="font-size:13px;line-height:1.8">
159	      <div>服务：<b>${r.service}</b> (${r.role})</div>
160	      <div>区域：${r.zone}</div>
161	      <div>运行状态：<span class="badge ${r.status}">${r.status}</span></div>
162	      <div>故障时段 P99：${r.p99_ms} ms · 队列/连接：${r.queue_depth}</div>
163	    </div>
164	    <div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">
165	      <button class="warn" ${r.status==='ISOLATED'?'disabled':''} onclick="setNode('${r.node_name}','ISOLATED')">隔离 (ISOLATE)</button>
166	      <button class="ok" ${r.status==='ACTIVE'?'disabled':''} onclick="setNode('${r.node_name}','ACTIVE')">恢复 (ACTIVE)</button>
167	    </div>`;
168	}
169	async function setNode(name, status){
170	  const feedback = document.getElementById('node-feedback');
171	  try {
172	    const response = await fetch('/api/nodes/'+encodeURIComponent(name), {method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({status})});
173	    if (!response.ok) throw new Error(`HTTP ${response.status}`);
174	    await loadAll();
175	    feedback.classList.remove('node-error');
176	    feedback.textContent = `${name} 的运行状态已更新为 ${status}。`;
177	  } catch (error) {
178	    feedback.classList.add('node-error');
179	    feedback.textContent = `无法确认 ${name} 的状态更新：${error.message}`;
180	  }
181	}
182	async function loadAll(){
183	  const n = await (await fetch('/api/nodes')).json();
184	  nodesCache = n.nodes;
185	  renderSvg();
186	  document.querySelector('#node-audit tbody').innerHTML = nodesCache.map(r => `<tr>
187	    <td>${r.node_name}</td><td><span class="badge ${r.status}">${r.status}</span></td>
188	    <td>${r.status_change_count}</td></tr>`).join('');
189	  if(selectedNode) selectNode(selectedNode);
190	
191	  const c = await (await fetch('/api/changes')).json();
192	  document.querySelector('#changes-table tbody').innerHTML = c.changes.map(r=>`<tr>
193	    <td>${r.ticket_id}</td><td>${r.service}</td><td><code>${r.commit_sha.slice(0,10)}</code></td><td>${r.bottleneck_span}</td>
194	    <td>${r.scheduled_window_utc8}</td><td><span class="badge ${r.canary_status}">${r.canary_status}</span></td>
195	    <td style="font-size:11px">${r.replay_summary||'-'}</td>
196	    <td><span class="badge ${r.locked?'LOCKED':r.status}">${r.status}${r.locked?' (LOCKED)':''}</span></td>
197	    <td style="white-space:nowrap">
198	      <button class="warn" ${r.locked?'disabled':''} onclick="runReplay('${r.ticket_id}')">触发灰度回放</button>
199	      <button class="ok" ${(r.locked||r.canary_status!=='CANARY_PASSED')?'disabled':''} onclick="approveChange('${r.ticket_id}')">签发排期</button>
200	    </td></tr>`).join('');
201	
202	  const b = await (await fetch('/api/batches')).json();
203	  document.querySelector('#batches-table tbody').innerHTML = b.batches.map(r=>`<tr>
204	    <td>${r.batch_id}</td><td>${r.batch_date}</td><td>${r.merchant_id}</td><td>${r.tier}</td><td>${r.currency}</td>
205	    <td><input size="10" id="bs-${r.batch_id}" value="${r.settled_amount_cny??''}" ${r.locked?'disabled':''}></td>
206	    <td><input size="4" id="bb-${r.batch_id}" value="${r.breached_tx_count??''}" ${r.locked?'disabled':''}></td>
207	    <td><input size="4" id="bd-${r.batch_id}" value="${r.duplicate_risk_count??''}" ${r.locked?'disabled':''}></td>
208	    <td><input size="8" id="bp-${r.batch_id}" value="${r.penalty_cny??''}" ${r.locked?'disabled':''}></td>
209	    <td><span class="badge ${r.audit_status}">${r.audit_status}</span></td>
210	    <td><button ${r.locked?'disabled':''} onclick="saveBatch('${r.batch_id}')">审计确认</button></td></tr>`).join('');
211	}
212	async function createChange(){
213	  const body = {
214	    service: document.getElementById('chg-svc').value,
215	    commit_sha: document.getElementById('chg-sha').value,
216	    bottleneck_span: document.getElementById('chg-span').value,
217	    scheduled_window_utc8: document.getElementById('chg-win').value,
218	    description: document.getElementById('chg-desc').value
219	  };
220	  const r = await fetch('/api/changes',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(body)});
221	  if(!r.ok) alert(await r.text());
222	  loadAll();
223	}
224	async function runReplay(id){
225	  const r = await fetch('/api/changes/'+id+'/canary-replay',{method:'POST',headers:{'X-CSRF-Token':CSRF}});
226	  if(!r.ok) alert(await r.text());
227	  loadAll();
228	}
229	async function approveChange(id){
230	  const r = await fetch('/api/changes/'+id+'/approve',{method:'POST',headers:{'X-CSRF-Token':CSRF}});
231	  if(!r.ok) alert(await r.text());
232	  loadAll();
233	}
234	async function saveBatch(id){
235	  const body = {
236	    settled_amount_cny: parseFloat(document.getElementById('bs-'+id).value),
237	    breached_tx_count: parseInt(document.getElementById('bb-'+id).value),
238	    duplicate_risk_count: parseInt(document.getElementById('bd-'+id).value),
239	    penalty_cny: parseFloat(document.getElementById('bp-'+id).value),
240	    audit_status: 'AUDITED'
241	  };
242	  const r = await fetch('/api/batches/'+id,{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(body)});
243	  if(!r.ok) alert(await r.text());
244	  loadAll();
245	}
246	loadAll();
247	</script>
