import asyncio, base64, sys
from playwright.async_api import async_playwright

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.connect_over_cdp('http://127.0.0.1:9222')
        ctx = browser.contexts[0]
        page = await ctx.new_page()
        await page.goto('http://127.0.0.1:9001/', wait_until='domcontentloaded', timeout=30000)
        print('perfetto page title:', await page.title())
        # fetch trace bytes inside browser (root uid passes proxy)
        info = await page.evaluate("""async () => {
            const r = await fetch('/traces/clearing_incident.pftrace');
            if (!r.ok) return {ok:false, status:r.status};
            const buf = new Uint8Array(await r.arrayBuffer());
            let bin=''; const CH=0x8000;
            for (let i=0;i<buf.length;i+=CH) bin += String.fromCharCode.apply(null, buf.subarray(i,i+CH));
            return {ok:true, size:buf.length, b64: btoa(bin)};
        }""")
        if not info.get('ok'):
            print('FETCH FAILED', info); sys.exit(1)
        data = base64.b64decode(info['b64'])
        open('/tmp/incident_work/clearing_incident.pftrace','wb').write(data)
        print('saved trace bytes:', len(data))
        await page.close()

asyncio.run(main())

