arguments.content:
import sys, json
from parse_trace import parse_trace

path = sys.argv[1] if len(sys.argv) > 1 else '/tmp/incident_work/clearing_incident.pftrace'
tracks, events, clocks = parse_trace(path)

def track_label(uuid):
    t = tracks.get(uuid, {})
    parts = []
    if 'thread_name' in t: parts.append(t['thread_name'])
    p = t.get('parent_uuid')
    if p and p in tracks: parts.append(tracks[p].get('process_name', ''))
    elif 'process_name' in t: parts.append(t['process_name'])
    return ' @ '.join(parts) or str(uuid)

# pair BEGIN/END per track using a stack
slices = []
stacks = {}
for e in events:
    u = e['track_uuid']; ty = e['type']
    if ty == 1:
        stacks.setdefault(u, []).append(e)
    elif ty == 2:
        st = stacks.get(u, [])
        if st:
            b = st.pop()
            slices.append({
                'name': b.get('name'), 'track': u, 'label': track_label(u),
                'begin': b['ts'], 'end': e['ts'], 'dur_ms': (e['ts'] - b['ts']) / 1e6,
                'annotations': b.get('annotations', []),
            })
        else:
            print('UNMATCHED END on', u, e['ts'])
for u, st in stacks.items():
    for b in st: print('UNCLOSED BEGIN', track_label(u), b.get('name'), b['ts'])

slices.sort(key=lambda x: -x['dur_ms'])
print('TOTAL SLICES:', len(slices))
print('=== TOP 25 LONGEST SLICES ===')
for sl in slices[:25]:
    print(f"{sl['dur_ms']:10.1f} ms  {sl['name']:45s} {sl['label']}  t={sl['begin']/1e9:.3f}s..{sl['end']/1e9:.3f}s")
    if sl['annotations']: print('      ann:', sl['annotations'])

print()
print('=== acquire_rule_lock slices (all) ===')
for sl in [x for x in slices if x['name'] == 'acquire_rule_lock']:
    print(f"{sl['dur_ms']:10.1f} ms  {sl['label']}  t={sl['begin']/1e9:.3f}..{sl['end']/1e9:.3f}  ann={sl['annotations']}")

print()
print('=== Mutex::wait top 10 ===')
for sl in [x for x in slices if x['name'] == 'Mutex::wait'][:10]:
    print(f"{sl['dur_ms']:10.1f} ms  {sl['label']}  t={sl['begin']/1e9:.3f}..{sl['end']/1e9:.3f}  ann={sl['annotations']}")

print()
print('=== annotations sample by name ===')
seen = set()
for sl in slices:
    nm = sl['name']
    if sl['annotations'] and nm not in seen:
        seen.add(nm)
        print(nm, '->', sl['annotations'][:6])

